// The bundled endpoint catalog (src/catalog.json, generated by
// scripts/sync-catalog.mjs from the API docs) and the lookups built on it.

import catalogData from "./catalog.json" with { type: "json" };

export interface CatalogParam {
  name: string;
  type: string;
  required: boolean;
  description: string;
  enum?: Array<string | number>;
  default?: unknown;
  example?: unknown;
}

export interface CatalogEndpoint {
  id: string;
  module: string;
  title: string;
  summary: string;
  auth: string;
  legacy: boolean;
  destructive: boolean;
  params: CatalogParam[];
}

export interface Catalog {
  modules: Array<{ module: string; title: string }>;
  endpoints: CatalogEndpoint[];
}

export const CATALOG = catalogData as unknown as Catalog;

const byId = new Map(CATALOG.endpoints.map((e) => [e.id, e]));

export const MODULES = CATALOG.modules.map((m) => m.module);

export function getEndpoint(id: string): CatalogEndpoint | undefined {
  return byId.get(id);
}

export function getParam(endpoint: CatalogEndpoint, name: string): CatalogParam | undefined {
  return endpoint.params.find((p) => p.name === name);
}

// Params nested inside an object or array param (customize.prefix,
// slots[].time) are documented in the catalog but checked by the API itself.
function isTopLevel(name: string): boolean {
  return !name.includes(".") && !name.includes("[");
}

function isBlank(value: unknown): boolean {
  if (value === undefined || value === null) return true;
  if (typeof value === "string") return value.trim() === "";
  if (Array.isArray(value)) return value.length === 0;
  return false;
}

// Required top-level params that are absent or blank in `params`.
export function missingRequired(
  endpoint: CatalogEndpoint,
  params: Record<string, unknown>
): CatalogParam[] {
  return endpoint.params.filter(
    (p) => p.required && isTopLevel(p.name) && isBlank(params[p.name])
  );
}

// --- Search ---

const SYNONYMS: Record<string, string[]> = {
  delete: ["remove"],
  remove: ["delete"],
  publish: ["post"],
  tweet: ["post"],
  analytics: ["report"],
  stats: ["report"],
  insights: ["report"],
  metrics: ["report"],
  scheduled: ["queue"],
  upcoming: ["queue"],
  team: ["member", "workspace"],
  tag: ["label"],
  edit: ["update"],
  change: ["update"],
  slot: ["schedule"],
  slots: ["schedule"],
  evergreen: ["library"],
  profile: ["account"],
  channel: ["account"],
  message: ["inbox"],
  messages: ["inbox"],
};

function words(text: string): string[] {
  return text
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter((w) => w.length > 1);
}

function stem(word: string): string {
  if (word.length > 4 && word.endsWith("ies")) return word.slice(0, -3) + "y";
  if (word.length > 3 && word.endsWith("es") && !word.endsWith("ses")) return word.slice(0, -1);
  if (word.length > 3 && word.endsWith("s") && !word.endsWith("ss")) return word.slice(0, -1);
  return word;
}

function matches(term: string, word: string): boolean {
  if (term === word) return true;
  const a = stem(term);
  const b = stem(word);
  if (a === b) return true;
  return a.length >= 4 && b.length >= 4 && (a.startsWith(b) || b.startsWith(a));
}

interface Indexed {
  endpoint: CatalogEndpoint;
  idWords: string[];
  titleWords: string[];
  summaryWords: string[];
  moduleWords: string[];
  paramWords: string[];
}

const index: Indexed[] = CATALOG.endpoints.map((endpoint) => ({
  endpoint,
  idWords: words(endpoint.id),
  titleWords: words(endpoint.title),
  summaryWords: words(endpoint.summary),
  moduleWords: words(endpoint.module),
  paramWords: [...new Set(endpoint.params.flatMap((p) => words(p.name)))],
}));

function scoreTerm(term: string, entry: Indexed): number {
  const hit = (list: string[]) => list.some((w) => matches(term, w));
  let score = 0;
  if (hit(entry.idWords)) score += 6;
  if (hit(entry.titleWords)) score += 4;
  if (hit(entry.moduleWords)) score += 3;
  if (hit(entry.summaryWords)) score += 2;
  if (hit(entry.paramWords)) score += 1;
  return score;
}

export interface SearchResult {
  endpoint: CatalogEndpoint;
  score: number;
}

// Ranks the catalog against the words of `query`, optionally within one
// module. An empty query lists the module (or the whole catalog) in order.
export function searchEndpoints(query: string, module?: string, limit = 10): SearchResult[] {
  const pool = module ? index.filter((e) => e.endpoint.module === module) : index;
  const terms = [...new Set(words(query))];
  const exactId = query.trim().toLowerCase();

  if (terms.length === 0) {
    return pool.slice(0, limit).map((e) => ({ endpoint: e.endpoint, score: 0 }));
  }

  const scored: SearchResult[] = [];
  for (const entry of pool) {
    let score = 0;
    let matched = 0;
    for (const term of terms) {
      let s = scoreTerm(term, entry);
      if (s === 0) {
        for (const syn of SYNONYMS[term] ?? []) {
          s = Math.max(s, scoreTerm(syn, entry) / 2);
        }
      }
      if (s > 0) matched++;
      score += s;
    }
    if (score === 0) continue;
    // Endpoints that match every word of the query come first.
    if (matched === terms.length) score += 5 * terms.length;
    // Prefer the endpoint whose id says just what was asked: feed_items over
    // feed_item_approve_all for "feed items".
    const unmatchedIdWords = entry.idWords.filter(
      (w) => !terms.some((t) => matches(t, w) || (SYNONYMS[t] ?? []).some((syn) => matches(syn, w)))
    ).length;
    score -= 1.5 * unmatchedIdWords;
    if (entry.endpoint.id === exactId) score += 100;
    scored.push({ endpoint: entry.endpoint, score });
  }
  scored.sort((a, b) => b.score - a.score || a.endpoint.id.localeCompare(b.endpoint.id));
  return scored.slice(0, limit);
}

// Closest ids to a mistyped one, for "unknown endpoint" errors.
export function suggestIds(id: string, limit = 5): string[] {
  return searchEndpoints(id.replace(/[^a-z0-9]+/gi, " "), undefined, limit).map(
    (r) => r.endpoint.id
  );
}
